vector<int> factorize(int n) {
    vector<int> factors;
    for (int i = 2; (long long)i * i <= n; i++)
        while (n % i == 0) {   // pull out i as many times as it divides
            factors.push_back(i);
            n /= i;
        }
    if (n > 1) factors.push_back(n);   // leftover prime
    return factors;
}

