List<Integer> factorize(int n) {
    List<Integer> factors = new ArrayList<>();
    for (int i = 2; (long) i * i <= n; i++)
        while (n % i == 0) {       // pull out i as many times as it divides
            factors.add(i);
            n /= i;
        }
    if (n > 1) factors.add(n);     // leftover prime
    return factors;
}

