function factorize(n) {
  const factors = [];
  for (let i = 2; i * i <= n; i++)
    while (n % i === 0) {          // pull out i as many times as it divides
      factors.push(i);
      n = n / i;
    }
  if (n > 1) factors.push(n);      // leftover prime
  return factors;
}
